-- ==========================================================
-- Auto-generated Import Script for Daşkənd Pro & Səmərqənd Pro
-- ==========================================================

BEGIN;

-- 1. Ensure Branches Exist
DO $$
DECLARE
  v_daskent_id UUID;
  v_semerqend_id UUID;
BEGIN
  SELECT branch_id INTO v_daskent_id FROM branch_translations WHERE name ILIKE '%Daşkənd%' OR name ILIKE '%Daskent%' LIMIT 1;
  IF v_daskent_id IS NULL THEN
    v_daskent_id := gen_random_uuid();
  END IF;

  SELECT branch_id INTO v_semerqend_id FROM branch_translations WHERE name ILIKE '%Səmərqənd%' OR name ILIKE '%Semerqend%' LIMIT 1;
  IF v_semerqend_id IS NULL THEN
    v_semerqend_id := gen_random_uuid();
  END IF;

  -- Create temp table to hold raw import data
  CREATE TEMP TABLE temp_import_customers (
    branch_type TEXT,
    first_name TEXT,
    last_name TEXT,
    phone TEXT
  ) ON COMMIT DROP;















  -- Insert Daşkənd customers avoiding duplicates
  SELECT gen_random_uuid(), t.first_name, t.last_name, t.phone, v_daskent_id, NOW()
  FROM temp_import_customers t
  WHERE t.branch_type = 'DASKENT'
    AND NOT EXISTS (
      SELECT 1 FROM customers c
      WHERE c.branch_id = v_daskent_id
        AND (
          (t.phone IS NOT NULL AND c.phone = t.phone)
          OR (t.phone IS NULL AND c.first_name = t.first_name AND c.last_name = t.last_name)
        )
    );

  -- Insert Səmərqənd customers avoiding duplicates
  SELECT gen_random_uuid(), t.first_name, t.last_name, t.phone, v_semerqend_id, NOW()
  FROM temp_import_customers t
  WHERE t.branch_type = 'SEMERQEND'
    AND NOT EXISTS (
      SELECT 1 FROM customers c
      WHERE c.branch_id = v_semerqend_id
        AND (
          (t.phone IS NOT NULL AND c.phone = t.phone)
          OR (t.phone IS NULL AND c.first_name = t.first_name AND c.last_name = t.last_name)
        )
    );

END $$;

COMMIT;
